using System;
using System.Linq;
using System.IO;
using System.Text;
using System.Collections;
using System.Collections.Generic;

class Solution
{
    static void Main(string[] args)
    {
        var nums = new List<int>();
        for (int i = 0; i < 5; i++)
        {
            nums.AddRange(Console.ReadLine().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).Select(int.Parse));            
        }
        int score = 0;
        score += CalculateRowScore(new List<int> { nums[0], nums[6], nums[12], nums[18], nums[24] }, true);
        score += CalculateRowScore(new List<int> { nums[4], nums[8], nums[12], nums[16], nums[20] }, true);
        score += CalculateRowScore(new List<int> { nums[0], nums[1], nums[2], nums[3], nums[4] }, false);
        score += CalculateRowScore(new List<int> { nums[5], nums[6], nums[7], nums[8], nums[9] }, false);
        score += CalculateRowScore(new List<int> { nums[10], nums[11], nums[12], nums[13], nums[14] }, false);
        score += CalculateRowScore(new List<int> { nums[15], nums[16], nums[17], nums[18], nums[19] }, false);
        score += CalculateRowScore(new List<int> { nums[20], nums[21], nums[22], nums[23], nums[24] }, false);
        score += CalculateRowScore(new List<int> { nums[0], nums[5], nums[10], nums[15], nums[20] }, false);
        score += CalculateRowScore(new List<int> { nums[1], nums[6], nums[11], nums[16], nums[21] }, false);
        score += CalculateRowScore(new List<int> { nums[2], nums[7], nums[12], nums[17], nums[22] }, false);
        score += CalculateRowScore(new List<int> { nums[3], nums[8], nums[13], nums[18], nums[23] }, false);
        score += CalculateRowScore(new List<int> { nums[4], nums[9], nums[14], nums[19], nums[24] }, false);
        Console.WriteLine(score);
    }

    private static int CalculateRowScore(List<int> values, bool diagonaal)
    {
        int score = 0;
        var pairs = values.GroupBy(p => p).ToDictionary(p => p.Key, q => q.Count());
        var trio = pairs.Where(i => i.Value == 3).Count();
        var pair = pairs.Where(i => i.Value == 2).Count();
        if (pairs.Where(i => i.Value == 5).Count() == 1)
            score += 10;
        else if (pairs.Where(i => i.Value == 4).Count() == 1)
            score += 6;
        else if (trio == 1 && pair == 1)
            score += 8;
        else if (pair == 2)
            score += 3;
        else if (trio == 1)
            score += 3;
        else if (pair == 1)
            score += 1;
        else
        {
            values = values.OrderBy(p => p).ToList();
            if (values[0] == values[1] - 1 && values[0] == values[2] - 2 && values[0] == values[3] - 3 && values[0] == values[4] - 4)
            {
                if (values.Contains(7))
                    score += 8;
                else
                    score += 12;
            }
        }
        if (diagonaal)
            score *= 2;
        return score;
    }
}
